-- webAVR v1: new, empty PostgreSQL database only. NOT a production upgrade script.
-- All IDs are generated by the application or deterministic migration mapping.
-- No Firebase credentials, legacy plaintext passwords, or real student data.
-- Business authorization is enforced by the API; helper functions are not RLS.
BEGIN;
CREATE SCHEMA webavr;
CREATE SCHEMA auth_private;
CREATE SCHEMA migration_private;
REVOKE ALL ON SCHEMA webavr, auth_private, migration_private FROM PUBLIC;

CREATE TABLE webavr.schema_versions (
  version text PRIMARY KEY, installed_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO webavr.schema_versions(version) VALUES ('v1-design');

CREATE TABLE webavr.users (
  id uuid PRIMARY KEY,
  display_name text NOT NULL CHECK (length(trim(display_name)) BETWEEN 1 AND 200),
  email text,
  state text NOT NULL DEFAULT 'pending_activation'
    CHECK (state IN ('pending_activation','active','disabled','needs_review','archived')),
  email_verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (email IS NULL OR email = trim(email)),
  CHECK (state <> 'active' OR (email IS NOT NULL AND email_verified_at IS NOT NULL))
);
-- No shared login email. Ambiguous legacy identities stay in restricted staging.
CREATE UNIQUE INDEX users_email_unique ON webavr.users(lower(email)) WHERE email IS NOT NULL;

CREATE TABLE auth_private.identities (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  provider text NOT NULL CHECK (provider IN ('local','firebase_legacy')),
  subject text NOT NULL CHECK (length(subject)>0),
  UNIQUE(provider, subject)
);
CREATE TABLE webavr.user_roles (
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  role text NOT NULL CHECK (role IN ('student','teacher','admin')),
  granted_by uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  granted_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  PRIMARY KEY (user_id, role),
  CHECK (revoked_at IS NULL OR revoked_at >= granted_at)
);
CREATE TABLE auth_private.credentials (
  user_id uuid PRIMARY KEY REFERENCES webavr.users(id) ON DELETE RESTRICT,
  password_hash text NOT NULL CHECK (password_hash LIKE '$argon2id$%'),
  changed_at timestamptz NOT NULL DEFAULT now(),
  must_reset boolean NOT NULL DEFAULT false
);
CREATE TABLE auth_private.tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  purpose text NOT NULL CHECK (purpose IN ('activate','reset_password','verify_email')),
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  revoked_at timestamptz,
  CHECK (expires_at > created_at)
);
CREATE INDEX tokens_user_idx ON auth_private.tokens(user_id,purpose);
CREATE TABLE auth_private.sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  token_hash text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  last_seen_at timestamptz,
  CHECK (expires_at > created_at)
);
CREATE INDEX sessions_user_idx ON auth_private.sessions(user_id);

CREATE TABLE webavr.classes (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  created_by uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','archived')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE webavr.class_memberships (
  id uuid PRIMARY KEY,
  class_id uuid NOT NULL REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  member_role text NOT NULL CHECK (member_role IN ('student','teacher')),
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at timestamptz,
  CHECK (left_at IS NULL OR left_at > joined_at)
);
CREATE UNIQUE INDEX one_open_membership
  ON webavr.class_memberships(class_id,user_id,member_role) WHERE left_at IS NULL;
CREATE INDEX memberships_user_idx ON webavr.class_memberships(user_id,class_id);

CREATE TABLE webavr.assets (
  id uuid PRIMARY KEY,
  owner_id uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  asset_kind text NOT NULL CHECK(asset_kind IN ('image','video','audio','document','archive','other')),
  storage_kind text NOT NULL CHECK(storage_kind IN ('local','external')),
  storage_key text UNIQUE,
  external_uri text,
  original_name text,
  mime_type text,
  byte_size bigint CHECK(byte_size >= 0),
  sha256 text CHECK(sha256 ~ '^[0-9a-f]{64}$'),
  width integer CHECK(width > 0), height integer CHECK(height > 0),
  state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','ready','missing','needs_review','archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(storage_key IS NULL OR (storage_key !~ '^/' AND storage_key !~ '(^|/)\.\.(/|$)')),
  CHECK((storage_kind='local' AND external_uri IS NULL)
     OR (storage_kind='external' AND storage_key IS NULL AND external_uri ~ '^https://')),
  CHECK(state <> 'ready' OR
     (storage_kind='external' AND external_uri IS NOT NULL) OR
     (storage_kind='local' AND storage_key IS NOT NULL AND sha256 IS NOT NULL
        AND byte_size IS NOT NULL AND mime_type IS NOT NULL))
);
CREATE INDEX assets_owner_idx ON webavr.assets(owner_id,state);
-- Equal hashes do not grant cross-owner access; authorization follows references.

CREATE TABLE webavr.courses (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),
  category text,
  description text NOT NULL DEFAULT '',
  visibility text NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),
  state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','needs_review','archived')),
  cover_asset_id uuid REFERENCES webavr.assets(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX courses_owner_idx ON webavr.courses(owner_id,state);
CREATE TABLE webavr.course_classes (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  class_id uuid NOT NULL REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  linked_at timestamptz NOT NULL DEFAULT now(),
  unlinked_at timestamptz,
  CHECK(unlinked_at IS NULL OR unlinked_at > linked_at)
);
CREATE UNIQUE INDEX one_open_course_class
  ON webavr.course_classes(course_id,class_id) WHERE unlinked_at IS NULL;
CREATE TABLE webavr.course_members (
  course_id uuid NOT NULL REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  member_role text NOT NULL CHECK(member_role IN ('learner','editor')),
  revoked_at timestamptz,
  PRIMARY KEY(course_id,user_id,member_role)
);

CREATE TABLE webavr.maps (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  title text NOT NULL,
  asset_id uuid REFERENCES webavr.assets(id) ON DELETE RESTRICT,
  state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','ready','needs_review','archived'))
);
CREATE TABLE webavr.course_maps (
  course_id uuid NOT NULL REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  map_id uuid NOT NULL REFERENCES webavr.maps(id) ON DELETE RESTRICT,
  sort_order integer NOT NULL DEFAULT 0 CHECK(sort_order >= 0),
  PRIMARY KEY(course_id,map_id)
);
CREATE TABLE webavr.map_markers (
  id uuid PRIMARY KEY,
  map_id uuid NOT NULL REFERENCES webavr.maps(id) ON DELETE RESTRICT,
  label text NOT NULL,
  x_ratio double precision, y_ratio double precision,
  legacy_x double precision, legacy_y double precision,
  state text NOT NULL DEFAULT 'needs_review' CHECK(state IN ('ready','needs_review','archived')),
  CHECK(x_ratio BETWEEN 0 AND 1), CHECK(y_ratio BETWEEN 0 AND 1),
  CHECK(state <> 'ready' OR (x_ratio IS NOT NULL AND y_ratio IS NOT NULL))
);
CREATE INDEX markers_map_idx ON webavr.map_markers(map_id);
CREATE TABLE webavr.tours (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  title text NOT NULL,
  state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','needs_review','archived')),
  entry_scene_id uuid,
  legacy_unlinked boolean NOT NULL DEFAULT false
);
CREATE TABLE webavr.scenes (
  id uuid PRIMARY KEY,
  tour_id uuid NOT NULL REFERENCES webavr.tours(id) ON DELETE RESTRICT,
  title text NOT NULL,
  image_asset_id uuid REFERENCES webavr.assets(id) ON DELETE RESTRICT,
  sort_order integer NOT NULL DEFAULT 0 CHECK(sort_order >= 0),
  projection text NOT NULL DEFAULT 'equirectangular' CHECK(projection IN ('equirectangular','cubemap','unknown')),
  state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','ready','needs_review','archived')),
  UNIQUE(tour_id,id),
  CHECK(state <> 'ready' OR image_asset_id IS NOT NULL)
);
ALTER TABLE webavr.tours ADD CONSTRAINT entry_scene_same_tour
  FOREIGN KEY(id,entry_scene_id) REFERENCES webavr.scenes(tour_id,id)
  ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX scenes_tour_idx ON webavr.scenes(tour_id,sort_order,id);
CREATE TABLE webavr.marker_tours (
  marker_id uuid NOT NULL REFERENCES webavr.map_markers(id) ON DELETE RESTRICT,
  tour_id uuid NOT NULL REFERENCES webavr.tours(id) ON DELETE RESTRICT,
  PRIMARY KEY(marker_id,tour_id)
);
CREATE TABLE webavr.hotspots (
  id uuid PRIMARY KEY,
  tour_id uuid NOT NULL,
  scene_id uuid NOT NULL,
  label text NOT NULL,
  pitch double precision NOT NULL CHECK(pitch BETWEEN -90 AND 90),
  yaw double precision NOT NULL CHECK(yaw BETWEEN -180 AND 180),
  state text NOT NULL DEFAULT 'ready' CHECK(state IN ('ready','needs_review','archived')),
  FOREIGN KEY(tour_id,scene_id) REFERENCES webavr.scenes(tour_id,id) ON DELETE RESTRICT,
  UNIQUE(tour_id,scene_id,id)
);
CREATE TABLE webavr.scene_links (
  id uuid PRIMARY KEY,
  tour_id uuid NOT NULL,
  source_scene_id uuid NOT NULL,
  target_scene_id uuid,
  label text NOT NULL,
  pitch double precision CHECK(pitch BETWEEN -90 AND 90),
  yaw double precision CHECK(yaw BETWEEN -180 AND 180),
  state text NOT NULL DEFAULT 'disabled' CHECK(state IN ('active','disabled','needs_review','archived')),
  FOREIGN KEY(tour_id,source_scene_id) REFERENCES webavr.scenes(tour_id,id) ON DELETE RESTRICT,
  FOREIGN KEY(tour_id,target_scene_id) REFERENCES webavr.scenes(tour_id,id) ON DELETE RESTRICT,
  CHECK(state <> 'active' OR (target_scene_id IS NOT NULL AND pitch IS NOT NULL AND yaw IS NOT NULL))
);
CREATE INDEX links_target_idx ON webavr.scene_links(tour_id,target_scene_id);

CREATE TABLE webavr.activities (
  id uuid PRIMARY KEY,
  hotspot_id uuid NOT NULL REFERENCES webavr.hotspots(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK(kind IN ('choice','explore','location','audio','video','document')),
  current_version integer NOT NULL DEFAULT 1 CHECK(current_version > 0),
  state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','needs_review','archived'))
);
CREATE TABLE webavr.activity_versions (
  activity_id uuid NOT NULL REFERENCES webavr.activities(id) ON DELETE RESTRICT,
  version integer NOT NULL CHECK(version>0),
  title text NOT NULL,
  public_payload jsonb NOT NULL CHECK(jsonb_typeof(public_payload)='object'),
  created_by uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(activity_id,version)
);
ALTER TABLE webavr.activities ADD CONSTRAINT activity_current_version_exists
  FOREIGN KEY(id,current_version) REFERENCES webavr.activity_versions(activity_id,version)
  ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE auth_private.question_keys (
  activity_id uuid NOT NULL,
  version integer NOT NULL,
  answer_payload jsonb NOT NULL CHECK(jsonb_typeof(answer_payload)='object'),
  FOREIGN KEY(activity_id,version) REFERENCES webavr.activity_versions(activity_id,version) ON DELETE RESTRICT,
  PRIMARY KEY(activity_id,version)
);
CREATE TABLE webavr.activity_assets (
  activity_id uuid NOT NULL,
  version integer NOT NULL,
  asset_id uuid NOT NULL REFERENCES webavr.assets(id) ON DELETE RESTRICT,
  FOREIGN KEY(activity_id,version) REFERENCES webavr.activity_versions(activity_id,version) ON DELETE RESTRICT,
  PRIMARY KEY(activity_id,version,asset_id)
);

CREATE TABLE webavr.learning_sessions (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  class_id uuid REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  created_by uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz,
  CHECK(ended_at IS NULL OR ended_at >= started_at)
);
CREATE TABLE webavr.session_members (
  session_id uuid NOT NULL REFERENCES webavr.learning_sessions(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  joined_at timestamptz NOT NULL DEFAULT now(), left_at timestamptz,
  PRIMARY KEY(session_id,user_id), CHECK(left_at IS NULL OR left_at >= joined_at)
);
CREATE TABLE webavr.attempts (
  id uuid PRIMARY KEY,
  activity_id uuid NOT NULL,
  activity_version integer NOT NULL,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  session_id uuid NOT NULL REFERENCES webavr.learning_sessions(id) ON DELETE RESTRICT,
  request_id uuid NOT NULL,
  submitted_answer jsonb NOT NULL,
  result text NOT NULL CHECK(result IN ('correct','incorrect','pending_review')),
  submitted_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(activity_id,activity_version) REFERENCES webavr.activity_versions(activity_id,version) ON DELETE RESTRICT,
  FOREIGN KEY(session_id,user_id) REFERENCES webavr.session_members(session_id,user_id) ON DELETE RESTRICT,
  UNIQUE(user_id,request_id), UNIQUE(id,user_id,activity_id,activity_version)
);
CREATE INDEX attempts_lookup_idx ON webavr.attempts(user_id,activity_id,submitted_at,id);
CREATE TABLE webavr.attempt_reviews (
  id uuid PRIMARY KEY,
  attempt_id uuid NOT NULL REFERENCES webavr.attempts(id) ON DELETE RESTRICT,
  reviewed_by uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  result text NOT NULL CHECK(result IN ('correct','incorrect','pending_review')),
  reason text NOT NULL CHECK(length(trim(reason))>0),
  reviewed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE webavr.activity_completions (
  user_id uuid NOT NULL, activity_id uuid NOT NULL, activity_version integer NOT NULL,
  attempt_id uuid NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(user_id,activity_id,activity_version),
  FOREIGN KEY(attempt_id,user_id,activity_id,activity_version)
    REFERENCES webavr.attempts(id,user_id,activity_id,activity_version) ON DELETE RESTRICT
);
CREATE TABLE webavr.learning_events (
  id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES webavr.learning_sessions(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  scene_id uuid REFERENCES webavr.scenes(id) ON DELETE RESTRICT,
  event_type text NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  client_time timestamptz,
  payload jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object'),
  request_id uuid NOT NULL,
  FOREIGN KEY(session_id,user_id) REFERENCES webavr.session_members(session_id,user_id) ON DELETE RESTRICT,
  UNIQUE(user_id,request_id)
);
CREATE INDEX events_session_idx ON webavr.learning_events(session_id,occurred_at,id);
CREATE INDEX events_user_idx ON webavr.learning_events(user_id,occurred_at,id);
CREATE TABLE webavr.current_positions (
  session_id uuid NOT NULL,
  user_id uuid NOT NULL,
  scene_id uuid NOT NULL REFERENCES webavr.scenes(id) ON DELETE RESTRICT,
  pitch double precision NOT NULL CHECK(pitch BETWEEN -90 AND 90),
  yaw double precision NOT NULL CHECK(yaw BETWEEN -180 AND 180),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(session_id,user_id),
  FOREIGN KEY(session_id,user_id) REFERENCES webavr.session_members(session_id,user_id) ON DELETE RESTRICT
);

CREATE TABLE webavr.conversations (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  course_id uuid REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  class_id uuid REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  scope text NOT NULL CHECK(scope IN ('private','course_support','legacy')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK(scope <> 'course_support' OR (course_id IS NOT NULL AND class_id IS NOT NULL))
);
CREATE TABLE webavr.conversation_members (
  conversation_id uuid NOT NULL REFERENCES webavr.conversations(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  revoked_at timestamptz,
  PRIMARY KEY(conversation_id,user_id)
);
CREATE TABLE webavr.messages (
  id uuid PRIMARY KEY,
  conversation_id uuid NOT NULL REFERENCES webavr.conversations(id) ON DELETE RESTRICT,
  actor_id uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  role text NOT NULL CHECK(role IN ('user','assistant','system')),
  content text NOT NULL DEFAULT '',
  state text NOT NULL DEFAULT 'completed' CHECK(state IN ('queued','running','completed','cancelled','failed','legacy')),
  request_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(conversation_id,request_id,role),
  CHECK(role <> 'user' OR actor_id IS NOT NULL)
);
CREATE INDEX messages_page_idx ON webavr.messages(conversation_id,created_at,id);
CREATE TABLE webavr.message_assets (
  message_id uuid NOT NULL REFERENCES webavr.messages(id) ON DELETE RESTRICT,
  asset_id uuid NOT NULL REFERENCES webavr.assets(id) ON DELETE RESTRICT,
  PRIMARY KEY(message_id,asset_id)
);
CREATE TABLE webavr.generation_jobs (
  id uuid PRIMARY KEY,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  conversation_id uuid REFERENCES webavr.conversations(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK(kind IN ('chat','image_generate','image_edit','lesson')),
  request_id uuid NOT NULL,
  state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','completed','cancelled','failed')),
  provider_response_id text,
  model text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz,
  UNIQUE(owner_id,request_id)
);
CREATE UNIQUE INDEX one_running_conversation_job ON webavr.generation_jobs(conversation_id)
  WHERE conversation_id IS NOT NULL AND state IN ('queued','running');
CREATE TABLE webavr.usage_records (
  id uuid PRIMARY KEY,
  job_id uuid NOT NULL REFERENCES webavr.generation_jobs(id) ON DELETE RESTRICT,
  owner_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  input_tokens bigint CHECK(input_tokens >= 0), output_tokens bigint CHECK(output_tokens >= 0),
  reserved_units numeric(18,6) NOT NULL DEFAULT 0 CHECK(reserved_units >= 0),
  final_units numeric(18,6) CHECK(final_units >= 0),
  recorded_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE webavr.survey_definitions (
  id uuid PRIMARY KEY,
  name text NOT NULL, version integer NOT NULL CHECK(version>0),
  algorithm_version text NOT NULL,
  definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),
  UNIQUE(name,version)
);
CREATE TABLE webavr.survey_attempts (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  definition_id uuid NOT NULL REFERENCES webavr.survey_definitions(id) ON DELETE RESTRICT,
  answers jsonb NOT NULL, scores jsonb, result text,
  request_id uuid NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id,request_id)
);
CREATE TABLE webavr.teaching_assignments (
  id uuid PRIMARY KEY,
  student_id uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  course_id uuid NOT NULL REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  class_id uuid NOT NULL REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  assigned_by uuid NOT NULL REFERENCES webavr.users(id) ON DELETE RESTRICT,
  strategy text NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz
);
CREATE UNIQUE INDEX one_current_strategy
  ON webavr.teaching_assignments(student_id,course_id,class_id) WHERE revoked_at IS NULL;

CREATE TABLE migration_private.runs (
  id uuid PRIMARY KEY,
  source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'),
  transformer_version text NOT NULL,
  state text NOT NULL CHECK(state IN ('planned','running','validated','failed','cutover')),
  started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz,
  UNIQUE(source_sha256,transformer_version)
);
CREATE TABLE migration_private.source_records (
  id uuid PRIMARY KEY,
  run_id uuid NOT NULL REFERENCES migration_private.runs(id) ON DELETE RESTRICT,
  source_path text NOT NULL,
  content_sha256 text NOT NULL CHECK(content_sha256 ~ '^[0-9a-f]{64}$'),
  disposition text NOT NULL CHECK(disposition IN ('imported','deduplicated','archived','needs_review','excluded')),
  target_kind text, target_id uuid,
  reason text NOT NULL,
  UNIQUE(run_id,source_path),
  CHECK(disposition NOT IN ('imported','deduplicated') OR (target_kind IS NOT NULL AND target_id IS NOT NULL))
);
CREATE TABLE migration_private.identity_map (
  id uuid PRIMARY KEY,
  source_record_id uuid NOT NULL REFERENCES migration_private.source_records(id) ON DELETE RESTRICT,
  legacy_subject text NOT NULL,
  user_id uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  confidence text NOT NULL CHECK(confidence IN ('verified','unresolved','conflict')),
  evidence jsonb NOT NULL DEFAULT '{}',
  CHECK(confidence <> 'verified' OR user_id IS NOT NULL)
);
CREATE TABLE migration_private.issues (
  id uuid PRIMARY KEY,
  source_record_id uuid NOT NULL REFERENCES migration_private.source_records(id) ON DELETE RESTRICT,
  code text NOT NULL,
  state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved','accepted_archive')),
  notes text NOT NULL,
  reviewed_by uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  reviewed_at timestamptz
);
CREATE TABLE migration_private.archives (
  id uuid PRIMARY KEY,
  source_record_id uuid NOT NULL REFERENCES migration_private.source_records(id) ON DELETE RESTRICT,
  subject_user_id uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  course_id uuid REFERENCES webavr.courses(id) ON DELETE RESTRICT,
  class_id uuid REFERENCES webavr.classes(id) ON DELETE RESTRICT,
  category text NOT NULL,
  occurred_at timestamptz,
  legacy_time_text text,
  time_quality text NOT NULL CHECK(time_quality IN ('verified','assumed_timezone','unknown')),
  redacted_payload jsonb NOT NULL,
  summary text NOT NULL,
  attribution text NOT NULL CHECK(attribution IN ('verified','unresolved','conflict')),
  CHECK(attribution <> 'verified' OR subject_user_id IS NOT NULL)
);
CREATE INDEX archives_subject_idx ON migration_private.archives(subject_user_id,category,occurred_at,id);
CREATE TABLE auth_private.audit_events (
  id uuid PRIMARY KEY,
  actor_id uuid REFERENCES webavr.users(id) ON DELETE RESTRICT,
  action text NOT NULL,
  target_kind text NOT NULL, target_id uuid,
  outcome text NOT NULL CHECK(outcome IN ('allowed','denied','failed')),
  reason text NOT NULL, request_id uuid NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

-- Protect redacted history from accidentally carrying legacy secret fields.
CREATE FUNCTION migration_private.contains_secret_key(doc jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE k text; v jsonb;
BEGIN
  IF jsonb_typeof(doc)='object' THEN
    FOR k,v IN SELECT key,value FROM jsonb_each(doc) LOOP
      IF lower(k) IN ('password','passwordhash','password_hash','private_key','apikey','api_key',
                       'access_token','accesstoken','idtoken','refresh_token','refreshtoken','token')
        OR migration_private.contains_secret_key(v) THEN RETURN true; END IF;
    END LOOP;
  ELSIF jsonb_typeof(doc)='array' THEN
    FOR v IN SELECT value FROM jsonb_array_elements(doc) LOOP
      IF migration_private.contains_secret_key(v) THEN RETURN true; END IF;
    END LOOP;
  END IF;
  RETURN false;
END $$;
ALTER TABLE migration_private.archives ADD CONSTRAINT archive_no_secret_keys
  CHECK(NOT migration_private.contains_secret_key(redacted_payload));
-- This key check is only defense in depth. The importer must also redact secret values in text/URLs.

CREATE FUNCTION webavr.has_role(actor uuid, wanted text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM webavr.users u JOIN webavr.user_roles r ON r.user_id=u.id
    WHERE u.id=actor AND u.state='active' AND r.role=wanted AND r.revoked_at IS NULL)
$$;

-- Learning-record access, not blanket permission for private chats or unverified archives.
CREATE FUNCTION webavr.can_read_learning_record(
  actor uuid, learner uuid, course uuid, class_scope uuid, happened timestamptz
) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS(SELECT 1 FROM webavr.users u WHERE u.id=actor AND u.state='active') AND (
    actor=learner OR webavr.has_role(actor,'admin') OR (
      class_scope IS NOT NULL AND course IS NOT NULL AND happened IS NOT NULL
      AND webavr.has_role(actor,'teacher')
      AND EXISTS(SELECT 1 FROM webavr.class_memberships cm
        JOIN webavr.classes c ON c.id=cm.class_id
        WHERE cm.class_id=class_scope AND cm.user_id=actor AND cm.member_role='teacher'
          AND c.state='active' AND cm.joined_at<=now() AND (cm.left_at IS NULL OR cm.left_at>now()))
      AND EXISTS(SELECT 1 FROM webavr.class_memberships sm
        WHERE sm.class_id=class_scope AND sm.user_id=learner AND sm.member_role='student'
          AND sm.joined_at<=happened AND (sm.left_at IS NULL OR sm.left_at>happened))
      AND EXISTS(SELECT 1 FROM webavr.course_classes cc
        WHERE cc.class_id=class_scope AND cc.course_id=course AND cc.linked_at<=happened
          AND (cc.unlinked_at IS NULL OR cc.unlinked_at>happened))
    )
  )
$$;

-- API should derive the context from the stored record/session, never from a client-supplied class.
CREATE FUNCTION webavr.can_read_session_record(
  actor uuid, learner uuid, session uuid, happened timestamptz
) RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT EXISTS(SELECT 1 FROM webavr.learning_sessions ls
    WHERE ls.id=session AND webavr.can_read_learning_record(actor,learner,ls.course_id,ls.class_id,happened))
$$;

-- Immutable evidence: corrections create a new version/attempt, never rewrite old grading.
CREATE FUNCTION webavr.reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'immutable history: create a new record or version' USING ERRCODE='23514'; END $$;
CREATE TRIGGER versions_immutable BEFORE UPDATE OR DELETE ON webavr.activity_versions
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();
CREATE TRIGGER attempts_immutable BEFORE UPDATE OR DELETE ON webavr.attempts
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();
CREATE TRIGGER attempt_reviews_immutable BEFORE UPDATE OR DELETE ON webavr.attempt_reviews
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();
CREATE TRIGGER question_keys_immutable BEFORE UPDATE OR DELETE ON auth_private.question_keys
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();
CREATE TRIGGER events_immutable BEFORE UPDATE OR DELETE ON webavr.learning_events
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON auth_private.audit_events
  FOR EACH ROW EXECUTE FUNCTION webavr.reject_history_mutation();

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA webavr,auth_private,migration_private FROM PUBLIC;
COMMIT;
